// EMMA Self-Builder: Cognitive Architect
const request = $json;

return [{
  json: {
    user: request.user || 'Irina',
    task: request.task || request.message,
    workflow_type: request.workflow_type || 'AUTO_DETECT',
    session_id: request.session_id || $execution.id,
    timestamp: new Date().toISOString()
  }
}];

// Parse analysis
const response = $json.text || $json.message?.content || '{}';
let analysis;
try {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  analysis = { workflow_type: 'CUSTOM', complexity: 5 };
}

return [{
  json: {
    ...items[0].json,
    analysis
  }
}];

// Parse generated workflow
const response = $json.text || $json.message?.content || '{}';
let workflowJson;
try {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  workflowJson = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  throw new Error('Parse failed');
}

const workflowName = `EMMA_COGNITIVE_${Date.now()}`;

return [{
  json: {
    workflow_name: workflowName,
    workflow_json: workflowJson,
    task: items[0].json.task,
    timestamp: new Date().toISOString()
  }
}];

const input = $json;
const candidates = [input.output, input.text, input.response, input.result, input.message?.content, input.data];
let raw = candidates.find(v => v !== undefined && v !== null && v !== '');
let parsed = {};
if (typeof raw === 'object') {
  parsed = raw;
  raw = JSON.stringify(raw);
} else if (typeof raw === 'string') {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : raw;
  const jsonMatch = body.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { parsed = JSON.parse(jsonMatch[0]); } catch (error) { parsed = { parse_error: error.message }; }
  }
}
return [{ json: { ...input, raw_llm_output: raw ?? '', ...parsed } }];

